<style>
.bridge-hub{--bh-border:#e5e7eb;--bh-muted:#6b7280;--bh-surface:#fff;--bh-inset:#f9fafb;display:grid;gap:1.25rem}.dark .bridge-hub{--bh-border:#374151;--bh-muted:#9ca3af;--bh-surface:#18181b;--bh-inset:#111114}.bridge-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:1rem}.bridge-card{border:1px solid var(--bh-border);border-radius:1rem;padding:1.5rem;background:var(--bh-surface)}.bridge-card h2{font-size:1.125rem;font-weight:650}.bridge-muted{color:var(--bh-muted);font-size:.875rem;line-height:1.6}.bridge-row{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap}.bridge-stack{display:grid;gap:.8rem}.bridge-actions{display:flex;gap:.65rem;flex-wrap:wrap;margin-top:1rem}.bridge-badge{display:inline-flex;align-items:center;gap:.4rem;font-size:.8rem;border:1px solid var(--bh-border);padding:.3rem .65rem;border-radius:999px}.bridge-dot{width:.5rem;height:.5rem;background:#9ca3af;border-radius:50%}.bridge-dot.online{background:#22c55e}.bridge-dot.pending{background:#f59e0b}.bridge-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}.bridge-step{padding:1rem;background:var(--bh-inset);border-radius:.75rem}.bridge-step strong{display:block;margin-bottom:.4rem}.bridge-code{font-family:monospace;font-size:1.2rem;letter-spacing:.08em;word-break:break-all;background:var(--bh-inset);padding:1rem;border:1px dashed var(--bh-border);border-radius:.75rem;display:block}.bridge-request{padding:1rem;border:1px solid var(--bh-border);border-radius:.75rem}.bridge-meta{display:grid;gap:.4rem;font-size:.875rem;overflow-wrap:anywhere}.bridge-history{margin-top:1rem;padding-top:1rem;border-top:1px solid var(--bh-border)}.bridge-history summary{cursor:pointer;font-size:.875rem;font-weight:600}.bridge-empty{padding:2rem;text-align:center}.bridge-card .bridge-help{margin-top:.75rem}.bridge-card .bridge-requests{margin-top:1rem}@media(max-width:640px){.bridge-steps{grid-template-columns:1fr}.bridge-card{padding:1rem}}
</style>
